def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease_parts is None:
            # No pre-release, this sorts after versions with pre-release
            prerelease_tuple = (1,)  # Tuple starting with 1 sorts after (0, ...)
        else:
            # Parse each pre-release identifier
            parsed_prerelease = []
            for identifier in prerelease_parts:
                if identifier.isdigit():
                    # All-digit identifier: compare numerically and sort before non-digit
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    # Non-digit identifier: compare by ASCII order
                    parsed_prerelease.append((1, identifier))
            prerelease_tuple = (0, tuple(parsed_prerelease))

        return (major, minor, patch, prerelease_tuple)

    # Create list of (sort_key, original_index, version_string)
    indexed_versions = [
        (parse_version(v), i, v)
        for i, v in enumerate(versions)
    ]

    # Sort by parse key, then by original index (to maintain input order for equal precedence)
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Extract sorted version strings
    return [v for _, _, v in indexed_versions]

